def parse(text):
    out = {}
    for line in text.splitlines():
        if line.strip():
            k, _, v = line.partition("=")
            out[k.strip()] = v.strip()
    return out

import unittest
from kv.parse import parse


class T(unittest.TestCase):
    def test_parse(self):
        self.assertEqual(parse("a=1\nb = 2\n"), {"a": "1", "b": "2"})

